"""Build the unpublished 6SW Week 5 job-readiness module."""

import asyncio, json, sys
import httpx
import build_5sw_wk1 as prior

common=prior.common; COURSE_ID=common.COURSE_ID; ROOT=common.ROOT
MODULE_NAME="6SW Wk5: Job Search, Applications, and Interviews"
TITLES={1:"PRACTICE: Job Search and Posting Evidence",2:"PRACTICE: Tailored Cover Letter",3:"PRACTICE: Application and References",4:"PRACTICE: Interview Readiness",5:"MAJOR 1: Job Skills, Application, and Mock Interview Portfolio"}

async def ensure_module(client):
    modules=await common.paged(client,f"/courses/{COURSE_ID}/modules"); found=next((m for m in modules if m["name"]==MODULE_NAME),None); data={"module[published]":"false"}
    if found:return await common.api(client,"PUT",f"/courses/{COURSE_ID}/modules/{found['id']}",data=data)
    data["module[name]"]=MODULE_NAME; return await common.api(client,"POST",f"/courses/{COURSE_ID}/modules",data=data)

QUESTIONS=[
("Q1 - screening","What happens before an applicant shares private information?","Screen the posting, source, employer, directions, and data request.",["Send an ID photo first.","Use any link in a message.","Contact every employer listed."],"Correct. Screening comes before disclosure or contact.","A posting does not automatically make a request safe."),
("Q2 - application","What should a student enter when a field does not apply in this simulation?","N/A when directions allow it; never invent information.",["A made-up credential","A family member's information","A random number"],"Correct. Complete, truthful, and consistent beats invented detail.","Never fabricate a field to make an application look full."),
("Q3 - references","What must happen before sharing a reference's contact information?","Ask the person for permission and explain the role.",["Assume a teacher agrees.","List a family member without asking.","Post the person's details publicly."],"Correct. Permission comes first.","Reference information belongs to another person and must not be shared without permission."),
("Q4 - appearance","Which interview-appearance rule is strongest?","Prepare for the workplace, task, safety requirements, format, and accommodations.",["Every interview requires a suit.","Expensive clothing earns points.","Eye contact is required for every person."],"Correct. Context, safety, and access come before fashion rules.","Appearance guidance is not universal, costly, body-based, or disability-based."),
("Q5 - privacy","Which classroom action is allowed?","Draft a fictional thank-you note and do not send it.",["Submit a real Social Security number.","Contact the fictional employer.","Publish a classmate's reference details."],"Correct. The simulation stays fictional and private.","No real application, message, contact, or personal-data disclosure is required."),]

async def upsert_quiz(client):
    qs=await common.paged(client,f"/courses/{COURSE_ID}/quizzes"); found=next((q for q in qs if q.get("title")==TITLES[4]),None)
    data={"quiz[title]":TITLES[4],"quiz[description]":"<p>Ungraded, unlimited-retry practice on screening, applications, references, interview context, and privacy.</p>","quiz[quiz_type]":"practice_quiz","quiz[published]":"false","quiz[allowed_attempts]":"-1","quiz[show_correct_answers]":"true","quiz[shuffle_answers]":"false"}
    quiz=await common.api(client,"PUT" if found else "POST",f"/courses/{COURSE_ID}/quizzes/{found['id']}" if found else f"/courses/{COURSE_ID}/quizzes",data=data); existing=await common.paged(client,f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions")
    for pos,(name,prompt,correct,wrong,yes,no) in enumerate(QUESTIONS,1):
        old=next((q for q in existing if q.get("question_name")==name),None); payload={"question":{"question_name":name,"question_text":prompt,"question_type":"multiple_choice_question","position":pos,"points_possible":1,"correct_comments":yes,"incorrect_comments":no,"answers":[{"answer_text":correct,"answer_weight":100}]+[{"answer_text":x,"answer_weight":0} for x in wrong]}}; path=f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions/{old['id']}" if old else f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions"; await common.api(client,"PUT" if old else "POST",path,json=payload)
    return await common.api(client,"GET",f"/courses/{COURSE_ID}/quizzes/{quiz['id']}")

def student_content(f,u):
    link,step=common.file_link,common.step
    data={
1:("Job Search and Posting Evidence","Screen a posting and connect requirements to truthful evidence before any application step.","<ul><li>put seven steps in order;</li><li>read the fixed posting;</li><li>match evidence and gaps;</li><li>choose a safe next action.</li></ul>","SEARCH",step(1,"Order the process","<p>Self-assess, find, screen, prepare, apply, interview, follow up.</p>")+step(2,"Read the fixed case","<p>Mark duties, required/preferred qualifications, source clues, and data boundaries.</p>")+step(3,"Match evidence honestly","<p>Use two truthful matches and one gap that is not hidden or invented.</p>")+step(4,"Screen and track","<p>Record safe next action and optional teacher-approved search plan.</p>"),"One skipped step + consequence.","<ul><li>seven steps;</li><li>two matches and one gap;</li><li>screening decision;</li><li>safe next action;</li><li>tracker entry.</li></ul>"),
2:("Tailored Cover Letter Simulation","Connect a specific posting to truthful applicant evidence in concise, human language.","<ul><li>plan the letter;</li><li>draft 3-4 short paragraphs;</li><li>audit accuracy and voice;</li><li>revise visibly.</li></ul>","COVER",step(1,"Use the fictional evidence card","<p>Do not add facts, credentials, work history, or results.</p>")+step(2,"Plan each job","<p>Opening, two evidence links, and courteous closing.</p>")+step(3,"Draft","<p>Tailor to Pecan Creek; keep the language plain and specific.</p>")+step(4,"Audit and revise","<p>Remove generic, inflated, unsupported, or private language.</p>"),"One before/after sentence + reason.","<ul><li>complete plan;</li><li>full draft;</li><li>accuracy/voice audit;</li><li>final fictional letter;</li><li>visible revision.</li></ul>"),
3:("Sample Application and References","Complete a fictional application accurately and apply permission-before-sharing reference protocol.","<ul><li>complete every applicable field;</li><li>use N/A correctly;</li><li>choose three reference roles;</li><li>draft but do not send a permission request.</li></ul>","APP",step(1,"Use only supplied facts","<p>Complete fictional identity, target, education, activities, experience, skills, and availability.</p>")+step(2,"Check consistency","<p>Application, posting, and cover letter evidence must agree.</p>")+step(3,"Choose reference roles","<p>Use people able to speak firsthand; do not enter real names/contact information.</p>")+step(4,"Ask first","<p>Draft an unsent respectful permission request and run the privacy audit.</p>"),"Why permission protects all three parties.","<ul><li>complete/N/A fields;</li><li>consistent evidence;</li><li>three appropriate roles and reasons;</li><li>unsent request;</li><li>privacy audit.</li></ul>"),
4:("Interview Readiness","Prepare evidence-based answers and privacy-safe interviewer follow-ups through a context-aware access route.","<ul><li>plan workplace/task/safety/format/access;</li><li>prepare eight answers;</li><li>prepare a follow-up;</li><li>review Quiz feedback.</li></ul>","READY",step(1,"Plan the context","<p>Research, timing, materials, safety, virtual backup, and accommodations.</p>")+step(2,"Build answer evidence","<p>Use situation/task, action, and result/reflection when helpful.</p>")+step(3,"Prepare as interviewer","<p>Ask relevant lawful questions, listen, and record neutral evidence.</p>")+step(4,"Practice Quiz","<p>Review every feedback explanation before Day 5.</p>"),"Chosen route + final preparation action.","<ul><li>readiness plan;</li><li>eight answer plans;</li><li>interviewer follow-up;</li><li>privacy boundary;</li><li>Quiz feedback reviewed.</li></ul>"),
5:("Mock Interview and Thank-You","Produce interviewer and interviewee evidence, apply feedback, and write a brief fictional follow-up.","<ul><li>complete two role/attempt rounds;</li><li>record evidence and feedback;</li><li>apply one revision;</li><li>write and audit a thank-you note.</li></ul>","MOCK",step(1,"Ready check","<p>Open posting/evidence, question plan, timer, access route, and feedback method.</p>")+step(2,"Round 1 and feedback","<p>Produce assessable interviewer/interviewee evidence and record one revision.</p>")+step(3,"Round 2","<p>Switch role or use the authorized equivalent; apply the revision.</p>")+step(4,"Write the fictional note","<p>Brief, specific, accurate, courteous, private, and not sent; self-score with the rubric.</p>"),"Strongest evidence + next revision.","<ul><li>two role/attempt records;</li><li>specific feedback;</li><li>visible revision;</li><li>final fictional note;</li><li>portfolio reflection and self-score.</li></ul>")}
    out={}
    for d,(title,purpose,today,key,steps,exit,done) in data.items():
        out[d]={"TITLE":title,"PURPOSE":purpose,"TODAY":today,"READY":f'<p>Open {link(f[key]["id"],"the student packet")} and <a href="{u[d]}">the private Canvas activity</a>.</p>',"STEPS":steps,"EXIT":f"<p>{exit}</p>","DONE":done,"SUPPORT":"<p>posting = oferta de empleo · application = solicitud · cover letter = carta de presentación · reference = referencia · interview = entrevista · follow-up = seguimiento.</p>","FALLBACK":"<p>Use the complete fictional case. Type, annotate, dictate, use paper, conference, private recording, or AAC. No real personal data, employer contact, public Discussion, family adult, camera, H&amp;L, Xello, or live job board is required.</p>"}
    out[5]["READY"] = f'<p>Open {link(f["MOCK"]["id"],"the six-page interview and thank-you record")}, {link(f["RUBRIC"]["id"],"the three-page Major 1 rubric")}, and <a href="{u[5]}">the private Major 1 portfolio Assignment</a>. Bring forward your Day 1 search/posting, Day 2 cover letter, and Day 3 application/reference evidence.</p>'
    out[5]["DONE"] = "<ul><li>search/posting evidence;</li><li>tailored cover letter;</li><li>fictional application;</li><li>reference roles and permission protocol;</li><li>two interview role/attempt records with revision;</li><li>final fictional thank-you note;</li><li>portfolio reflection and 24-point self-score.</li></ul>"
    return out

def teacher_content(f):
    link,flow=common.file_link,common.flow; c="#5d3f6a"
    data={1:("Job Search and Posting Evidence","d(6)(A)","SEARCH","Seven-step process, posting evidence, screening, and safe next action.","Require two truthful matches, one honest gap, source/privacy screening, and a safe next action. Trim optional live search first."),2:("Tailored Cover Letter","d(7)(B)","COVER","Plan, full draft, audit, final fictional letter, and visible revision.","Do not reward invented enthusiasm or formulaic slop. Require two supplied evidence links. Trim peer review first."),3:("Application and References","d(7)(C), d(7)(D)","APP","Complete fictional application plus three reference roles/reasons and permission protocol.","No real names/contact data. Full evidence uses N/A appropriately and stays consistent. Trim comparison first."),4:("Interview Readiness","d(6)(B)","READY","Context/access plan, eight answers, interviewer follow-up, and Quiz feedback.","Appearance is workplace/task/safety/format/access based. No cost, body, gender, culture, religion, disability, eye-contact, handshake, or camera rule. Trim partner rehearsal first."),5:("Mock Interview and Follow-Up","d(6)(B), d(6)(C), d(7)(B)","MOCK","Two role/attempt records, feedback, applied revision, thank-you note, reflection, and rubric.","Use private equivalent routes. Score accuracy, relevance, organization, privacy, response, and revision—not accent, confidence, memorization, or camera use.")}
    out={}
    for d,(title,teks,key,evidence,monitor) in data.items():
        out[d]={"TITLE":title,"SUBTITLE":f"50 minutes · TEKS {teks}","ALERT":"<strong>Boundary:</strong> Complete fictional case only. No real application, contact, message, identity data, reference contact, or public posting.","PREP":f'<ul><li>Post {link(f[key]["id"],"the student packet")} and day interaction.</li><li>Open the coordinated Student Guide.</li><li>Confirm private/access routes before class.</li></ul>',"EVIDENCE":f"<p>{evidence}</p>","FLOW":flow(c,"Warm-up · 5","Activate the day's decision.")+flow("#4c8b38","Model · 8","One accurate teacher example.")+flow("#155d7a","Build evidence · 22","Private fixed-case work.")+flow("#d39b22","Audit/practice/revise · 10","Make the change visible.")+flow(c,"Exit · 5","One conclusion and next check."),"MONITOR":f"<p>{monitor}</p>","RESOURCES":'<p><a href="https://www.careeronestop.org/JobSearch/job-search.aspx">CareerOneStop Job Search</a> · <a href="https://www.careeronestop.org/JobSearch/Interview/interview-and-negotiate.aspx">CareerOneStop Interview Guidance</a>.</p>',"SUPPORT":"<p>Short identity fields request supplied labels only. Evidence and rationale prompts receive 3-8 full-width lines; the cover letter and thank-you each receive a full draft page; eight questions span four pages; the application is eight pages. Accept typing, dictation, annotation, enlarged print, paper, conference, recording, or AAC.</p>","FALLBACK":"<p>The fixed case is complete. H&amp;L, Xello, Rung 5, live job boards, real contact/data, family participation, public performance/Discussion, and camera use are optional or excluded—not required.</p>"}
    out[5]["EVIDENCE"] = "<p><strong>Major 1 in the approved 6SW assessment map:</strong> search/posting evidence, tailored cover letter, fictional application, reference protocol, two interview role/attempt records with revision, final thank-you note, reflection, and rubric. Keep unpublished until the Canvas review gate passes.</p>"
    return out

async def main():
    token=sys.stdin.readline().strip()
    if not token: raise SystemExit("Canvas token required on stdin")
    async with httpx.AsyncClient(headers={"Authorization":f"Bearer {token}"},timeout=120) as client:
        module=await ensure_module(client); path="course files/CCR Materials/6SW/Wk5"; folder=await common.ensure_folder(client,path)
        names={"SEARCH":"6sw-wk5-job-search-and-posting-evidence.pdf","COVER":"6sw-wk5-cover-letter-simulation.pdf","APP":"6sw-wk5-application-and-references.pdf","READY":"6sw-wk5-interview-readiness.pdf","MOCK":"6sw-wk5-mock-interview-and-thank-you.pdf","RUBRIC":"6sw-wk5-job-skills-rubric.pdf"}; files={k:await common.upload(client,ROOT/"docs/resources/worksheets"/n,path) for k,n in names.items()}
        quiz=await upsert_quiz(client); assignments={}
        for d,key in {1:"SEARCH",2:"COVER",3:"APP"}.items(): assignments[d]=await common.upsert_assignment(client,TITLES[d],"<p>Complete privately by annotation, upload, typed labeled responses, dictation, or paper.</p>",["student_annotation","online_upload","online_text_entry"],files[key]["id"])
        assignments[5]=await common.upsert_assignment(client,TITLES[5],"<p>Submit the complete private six-part portfolio: search/posting evidence, tailored cover letter, fictional application, reference roles/permission protocol, mock-interview role evidence with revision, and fictional thank-you correspondence, plus reflection and self-score. Keep unpublished until the Canvas review gate passes.</p>",["media_recording","student_annotation","online_upload","online_text_entry"],files["MOCK"]["id"])
        urls={d:f"/courses/{COURSE_ID}/assignments/{a['id']}" for d,a in assignments.items()}; urls[4]=f"/courses/{COURSE_ID}/quizzes/{quiz['id']}"
        s,t=student_content(files,urls),teacher_content(files); labels={1:"Job Search and Posting Evidence",2:"Tailored Cover Letter",3:"Application and References",4:"Interview Readiness",5:"Mock Interview and Follow-Up"}; interactions={1:("Assignment",assignments[1]["id"],TITLES[1]),2:("Assignment",assignments[2]["id"],TITLES[2]),3:("Assignment",assignments[3]["id"],TITLES[3]),4:("Quiz",quiz["id"],TITLES[4]),5:("Assignment",assignments[5]["id"],TITLES[5])}; order=[]; pages={}
        for d in range(1,6):
            ht=f"Day {d} · {labels[d]}"; h=await prior.upsert_item(client,module["id"],"SubHeader",None,ht); order.append(("SubHeader",h["id"],ht)); st=f"STUDENT: 6SW Wk5 Day {d} - {labels[d]}"; sp=await common.upsert_page(client,st,common.render("6sw-wk5-student.html",{"COURSE_ID":COURSE_ID,"DAY":d,**s[d]})); tt=f"TEACHER: 6SW Wk5 Day {d} Facilitator Guide"; tp=await common.upsert_page(client,tt,common.render("6sw-wk5-teacher.html",{"COURSE_ID":COURSE_ID,"DAY":d,"STUDENT_PAGE_URL":sp["url"],**t[d]})); await prior.upsert_item(client,module["id"],"Page",tp["url"],tt); await prior.upsert_item(client,module["id"],"Page",sp["url"],st); kind,key,title=interactions[d]; await prior.upsert_item(client,module["id"],kind,key,title); order += [("Page",tp["url"],tt),("Page",sp["url"],st),(kind,key,title)]; pages[d]={"teacher":tp,"student":sp}
        items=await common.paged(client,f"/courses/{COURSE_ID}/modules/{module['id']}/items")
        for pos,(kind,key,title) in enumerate(order,1):
            item=next(i for i in items if (kind=="SubHeader" and i.get("id")==key) or (kind=="Page" and i.get("page_url")==key) or (kind in ("Assignment","Quiz") and i.get("content_id")==key)); await common.api(client,"PUT",f"/courses/{COURSE_ID}/modules/{module['id']}/items/{item['id']}",data={"module_item[position]":pos,"module_item[title]":title})
        final=await common.paged(client,f"/courses/{COURSE_ID}/modules/{module['id']}/items"); module=await common.api(client,"GET",f"/courses/{COURSE_ID}/modules/{module['id']}"); print(json.dumps({"module":{"id":module["id"],"published":module["published"]},"folder":{"id":folder["id"],"locked":folder["locked"]},"files":{k:x["id"] for k,x in files.items()},"quiz":{"id":quiz["id"],"published":quiz.get("published")},"assignments":{str(k):{"id":x["id"],"published":x.get("published")} for k,x in assignments.items()},"pages":{str(d):{k:{"url":x["url"],"published":x["published"]} for k,x in p.items()} for d,p in pages.items()},"items":[{"position":i["position"],"type":i["type"],"title":i["title"]} for i in final]},indent=2))

if __name__=="__main__": asyncio.run(main())
